import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  if (!user) return null;

  return (
    <nav style={styles.nav}>
      <Link to="/dashboard" style={styles.brand}>DRMS</Link>
      <div style={styles.links}>
        <Link to="/dashboard" style={styles.link}>Dashboard</Link>
        <Link to="/documents" style={styles.link}>Documents</Link>
        <Link to="/upload" style={styles.link}>Upload</Link>
        {(user.role === 'Admin' || user.role === 'Auditor') && (
          <>
            <Link to="/reports" style={styles.link}>Reports</Link>
            <Link to="/audit" style={styles.link}>Audit Logs</Link>
          </>
        )}
        <span style={styles.userInfo}>{user.name} ({user.role})</span>
        <button onClick={handleLogout} style={styles.btn}>Logout</button>
      </div>
    </nav>
  );
}

const styles = {
  nav: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 24px', background: '#1a237e', color: '#fff' },
  brand: { color: '#fff', textDecoration: 'none', fontSize: '20px', fontWeight: 'bold' },
  links: { display: 'flex', alignItems: 'center', gap: '16px', flexWrap: 'wrap' },
  link: { color: '#e8eaf6', textDecoration: 'none', fontSize: '14px' },
  userInfo: { color: '#c5cae9', fontSize: '13px' },
  btn: { background: '#ef5350', color: '#fff', border: 'none', padding: '6px 14px', borderRadius: '4px', cursor: 'pointer' }
};
